function updateLeadSelectionControls(){const visible=new Set(visibleLeadIds),selectedVisible=visibleLeadIds.filter(id=>selectedLeadIds.has(id)).length,allVisible=visibleLeadIds.length>0&&selectedVisible===visibleLeadIds.length,checkbox=document.querySelector('#leadSelectAll'),button=document.querySelector('#selectAllLeads'),bar=document.querySelector('#leadBulkBar'),count=document.querySelector('#leadSelectedCount');if(checkbox){checkbox.checked=allVisible;checkbox.indeterminate=selectedVisible>0&&!allVisible}if(button){button.textContent=allVisible?'Tout désélectionner':`Tout sélectionner${visible.size?` (${visible.size})`:''}`;button.disabled=!visible.size}if(count)count.textContent=selectedLeadIds.size;if(bar)bar.hidden=!selectedLeadIds.size}
