function statusesModal(){modal('Gérer les étapes du pipeline',`<p class="status-manager-intro">Ajoutez, renommez ou supprimez les étapes qui correspondent à votre processus commercial.</p><div class="status-manager">${S.map(s=>`<div class="status-manager-row"><span>${esc(s)}</span>${reservedStatuses.has(s)?'<small>Étape système</small>':`<button class="btn" data-edit-status="${esc(s)}">Modifier</button><button class="btn danger" data-delete-status="${esc(s)}">Supprimer</button>`}</div>`).join('')}</div><div class="status-add"><input id="newStatusLabel" maxlength="60" placeholder="Nom de la nouvelle étape"><button class="btn blue" id="addStatus">＋ Ajouter</button></div>`,'<button class="btn" id="closeStatuses">Fermer</button>','status-manager-modal');closeStatuses.onclick=closeModal;addStatus.onclick=async()=>{const label=newStatusLabel.value.trim();if(!label)return toast('Saisissez un intitulé',true);try{replaceStatuses(await api('/api/crm/statuses',{method:'POST',body:JSON.stringify({label})}));closeModal();render();toast('Étape ajoutée')}catch(e){toast(e.message,true)}};document.querySelectorAll('[data-edit-status]').forEach(button=>button.onclick=()=>editStatusModal(button.dataset.editStatus));document.querySelectorAll('[data-delete-status]').forEach(button=>button.onclick=()=>deleteStatus(button.dataset.deleteStatus))}
function editStatusModal(oldLabel){modal('Modifier l’étape',`<div class="field"><label>Intitulé</label><input id="editStatusLabel" maxlength="60" value="${esc(oldLabel)}"></div>`,`<button class="btn" id="cancelStatusEdit">Annuler</button><button class="btn blue" id="saveStatusEdit">Enregistrer</button>`);cancelStatusEdit.onclick=statusesModal;saveStatusEdit.onclick=async()=>{const label=editStatusLabel.value.trim();if(!label)return toast('Saisissez un intitulé',true);try{const result=await api(`/api/crm/statuses/${encodeURIComponent(oldLabel)}`,{method:'PATCH',body:JSON.stringify({label})});contacts.forEach(c=>{if(c.statut===oldLabel)c.statut=result.replacement});replaceStatuses(result.statuses);closeModal();render();toast('Étape renommée')}catch(e){toast(e.message,true)}}}
