const calendarDateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
function calendarFormationTone(appointment,contact={}){
  const value=[contact.formation,appointment?.name,appointment?.event_type_name].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
  if(value.includes('DESP')||value.includes('DIRIGEANT'))return'desp';
  if(value.includes('SSIAP')||value.includes('SECURITE INCENDIE'))return'ssiap';
  if(value.includes('A3P')||value.includes('APR')||value.includes('GARDE DU CORPS')||value.includes('PROTECTION PHYSIQUE'))return'a3p';
  if(value.includes('VTC')||value.includes('CHAUFFEUR'))return'vtc';
  if(value.includes('APS')||value.includes('PREVENTION ET DE SECURITE'))return'aps';
  return'default';
}
function calendarAppointmentTreatment(appointment){
  const treatments={
    answered:{tone:'answered',label:'Traité · A répondu'},
    no_answer:{tone:'no-answer',label:'Traité · Sans réponse'},
  };
  return treatments[String(appointment?.response_status||'').toLowerCase()]||null;
}
function changeCalendarDate(days){const date=new Date(`${calendarSelectedDate}T12:00:00`);date.setDate(date.getDate()+days);calendarSelectedDate=calendarDateKey(date);calendarDate.value=calendarSelectedDate;loadCalendar()}
function calendarPage(){calendarSelectedDate=calendarDateKey(new Date());page.innerHTML=header('AGENDA COMMERCIAL','Calendrier','Les rendez-vous Calendly de la journée sélectionnée.')+`<section class="calendar-shell"><div class="calendar-toolbar"><div class="calendar-date-picker"><button class="btn calendar-nav" id="calendarPrevious" aria-label="Jour précédent">‹</button><label for="calendarDate"><span>Date affichée</span><input id="calendarDate" type="date" value="${calendarSelectedDate}"></label><button class="btn calendar-nav" id="calendarNext" aria-label="Jour suivant">›</button><button class="btn" id="calendarToday">Aujourd’hui</button><span class="calendar-live"><i></i> Synchronisé avec Calendly</span></div><button class="btn blue" id="calendarRefresh">↻ Actualiser</button></div><div id="calendarContent" class="calendar-loading"><span class="sync-spinner"></span><p>Chargement de votre agenda…</p></div></section>`;calendarPrevious.onclick=()=>changeCalendarDate(-1);calendarNext.onclick=()=>changeCalendarDate(1);calendarToday.onclick=()=>{calendarSelectedDate=calendarDateKey(new Date());calendarDate.value=calendarSelectedDate;loadCalendar()};calendarDate.onchange=()=>{if(calendarDate.value){calendarSelectedDate=calendarDate.value;loadCalendar()}};calendarRefresh.onclick=()=>loadCalendar(true);loadCalendar()}
async function loadCalendar(manual=false){const root=document.querySelector('#calendarContent'),button=document.querySelector('#calendarRefresh');if(!root)return;if(manual){button.disabled=true;root.className='calendar-loading';root.innerHTML='<span class="sync-spinner"></span><p>Actualisation de votre agenda…</p>'}try{const data=await api('/api/crm/calendly/appointments'),date=new Date(`${calendarSelectedDate}T12:00:00`),items=(data.appointments||[]).filter(a=>a.status!=='canceled'&&calendarDateKey(new Date(a.start_time))===calendarSelectedDate).sort((a,b)=>new Date(a.start_time)-new Date(b.start_time));root.className='calendar-days';root.innerHTML=`<section class="calendar-day"><header><div class="calendar-date"><strong>${date.getDate()}</strong><span>${date.toLocaleDateString('fr-FR',{weekday:'long'})}<small>${date.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</small></span></div><span>${items.length} rendez-vous</span></header>${items.length?`<div class="calendar-events">${items.map(a=>{const c=a.contact||{},name=displayName(c)||a.invitee_name||'Invité Calendly',treatment=calendarAppointmentTreatment(a),treatmentClass=treatment?` calendar-treated-${treatment.tone}`:'';return `<article class="calendar-event calendar-training-${calendarFormationTone(a,c)}${treatmentClass}" ${c.id?`data-id="${c.id}"`:''}><time>${new Date(a.start_time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</time><i></i><div><b>${esc(a.name||'Rendez-vous Calendly')}</b><span>${esc(name)}${c.formation?` · ${esc(c.formation)}`:''}</span><small class="calendar-host">Interlocuteur : ${esc(a.host_name||'Non renseigné')}</small></div><div class="calendar-event-side">${treatment?`<span class="calendar-treatment-badge ${treatment.tone}">✓ ${esc(treatment.label)}</span>`:''}<span class="calendar-duration">${a.end_time?Math.round((new Date(a.end_time)-new Date(a.start_time))/60000)+' min':'Calendly'}</span>${appointmentResponseControl(a)}</div></article>`}).join('')}</div>`:'<div class="calendar-empty"><b>Aucun rendez-vous ce jour-là</b><span>Choisissez une autre date pour consulter l’agenda.</span></div>'}</section>`;bindRows();bindAppointmentResponseControls(items,()=>loadCalendar())}catch(e){root.className='activity-empty error-text';root.textContent=e.message}finally{if(button){button.disabled=false;button.textContent='↻ Actualiser'}}}
