function reminderDay(dateKey,items){const date=new Date(`${dateKey}T12:00:00`);return `<section class="calendar-day"><header><div class="calendar-date"><strong>${date.getDate()}</strong><span>${date.toLocaleDateString('fr-FR',{weekday:'long'})}<small>${date.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</small></span></div><span>${items.length} relance${items.length>1?'s':''}</span></header><div class="calendar-events">${items.map(reminderEvent).join('')}</div></section>`}
function renderReminders(){const root=document.querySelector('#reminderContent'),toggle=document.querySelector('#reminderShowAll');if(!root)return;toggle.textContent=reminderShowAll?'Voir la journée sélectionnée':'Voir toutes les relances';document.querySelectorAll('#reminderPrevious,#reminderNext,#reminderToday,#reminderDate').forEach(control=>control.disabled=reminderShowAll);const all=contacts.filter(c=>c.statut==='A relancer'&&c.relance_date).sort((a,b)=>a.relance_date.localeCompare(b.relance_date)||displayName(a).localeCompare(displayName(b),'fr'));if(reminderShowAll){const groups=all.reduce((dates,c)=>({...dates,[c.relance_date]:[...(dates[c.relance_date]||[]),c]}),{});root.innerHTML=all.length?Object.entries(groups).map(([date,items])=>reminderDay(date,items)).join(''):'<div class="calendar-empty"><b>Aucune relance planifiée</b><span>Les prochaines relances apparaîtront ici dès leur création.</span></div>'}else{const items=all.filter(c=>c.relance_date===reminderSelectedDate);root.innerHTML=items.length?reminderDay(reminderSelectedDate,items):`<section class="calendar-day"><div class="calendar-empty"><b>Aucune relance ce jour-là</b><span>Choisissez une autre date ou affichez toutes les relances.</span></div></section>`}bindRows()}
function bindRows(){document.querySelectorAll('[data-id]').forEach(row=>{const opensNewTab=C.section==='pistes'&&row.closest('#resultTable');if(opensNewTab){row.dataset.openNewTab='true';const person=row.querySelector('.person');if(person&&person.tagName!=='A'){const link=document.createElement('a');link.className=person.className;link.href=contactSheetUrl(row.dataset.id);link.target='_blank';link.rel='noopener';link.innerHTML=person.innerHTML;person.replaceWith(link)}}const isControl=event=>event.target.closest('input,button,select,textarea,label,a');row.onclick=event=>{if(isControl(event))return;row.dataset.openNewTab?openContactInNewTab(row.dataset.id):showContact(row.dataset.id)};row.onauxclick=event=>{if(event.button!==1||!row.dataset.openNewTab||isControl(event))return;openContactInNewTab(row.dataset.id)}})}
function plannedRelances(c){return(c.relances||[]).filter(item=>item.status==='scheduled').sort((a,b)=>String(a.scheduled_date||'').localeCompare(String(b.scheduled_date||'')))}
function relanceDateMeta(value){const date=new Date(`${value}T12:00:00`),today=new Date();today.setHours(12,0,0,0);const days=Math.round((date-today)/86400000),valid=!Number.isNaN(date.getTime());if(!valid)return{day:'—',month:'Date',long:'Date non renseignée',relative:'À préciser',tone:'neutral'};const long=date.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),month=date.toLocaleDateString('fr-FR',{month:'short'}).replace('.','');if(days<0)return{day:date.getDate(),month,long,relative:`En retard de ${Math.abs(days)} j`,tone:'overdue'};if(days===0)return{day:date.getDate(),month,long,relative:"Aujourd’hui",tone:'today'};if(days===1)return{day:date.getDate(),month,long,relative:'Demain',tone:'soon'};return{day:date.getDate(),month,long,relative:`Dans ${days} j`,tone:'future'}}
