  const plannedHtml=planned.length?planned.map(item=>{const meta=relanceDateMeta(item.scheduled_date);return`<article class="relance-item relance-${meta.tone}" data-relance-id="${esc(item.id)}"><div class="relance-date-card"><strong>${meta.day}</strong><span>${esc(meta.month)}</span></div><div class="relance-item-main"><div class="relance-item-title"><div><span class="relance-status ${meta.tone}">${esc(meta.relative)}</span><h3>${esc(meta.long)}</h3></div><div class="relance-item-controls"><button class="relance-reschedule" data-relance-reschedule type="button">Reprogrammer</button><button class="relance-delete" data-relance-delete type="button" aria-label="Supprimer la relance du ${esc(meta.long)}">Supprimer</button></div></div><p>Relance téléphonique prévue · créée par ${esc(item.created_by||'Équipe Intégrale')}</p><div class="relance-actions"><button class="btn relance-answered" data-relance-answered type="button">${crmIcon('check')}<span>A répondu</span></button><button class="btn relance-no-answer" data-relance-no-answer type="button">${crmIcon('phone')}<span>Pas de réponse</span></button></div></div></article>`}).join(''):`<div class="relance-empty"><span class="relance-empty-icon">${crmIcon('alarm')}</span><h3>Aucune relance prévue</h3><p>Planifiez la prochaine prise de contact pour qu’elle ne soit jamais oubliée.</p><button class="btn blue" id="emptyPlanRelance" type="button">Planifier une relance</button></div>`;
