      rangeLabel.textContent=`${rangeStart.toLocaleDateString('fr-FR',{day:'numeric',month:'short'})} – ${new Date(windowEnd.getTime()-86400000).toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}`;
