const crmTemplateVariables=[['{{ prenom }}','Prénom'],['{{ nom }}','Nom'],['{{ email }}','Adresse e-mail'],['{{ telephone }}','Téléphone'],['{{ formation }}','Formation'],['{{ lieu }}','Lieu'],['{{ statut }}','Statut CRM'],['{{ dates_formation }}','Dates de formation'],['{{ prochaines_dates }}','Prochaines sessions disponibles'],['{{ date_rdv_du_jour }}','Date du RDV téléphonique du jour'],['{{ heure_rdv_du_jour }}','Heure du RDV téléphonique du jour'],['{{ date_heure_rdv_du_jour }}','Date et heure du RDV téléphonique du jour'],['{{ lien_rdv_calendly }}','Lien du RDV Calendly selon la formation']];
function templateVariablesHtml(){return `<section class="card template-variables"><div class="card-head"><div><h2>Variables disponibles</h2><small>Copiez une variable dans l’objet ou le contenu d’un e-mail ou d’un SMS. Elle sera remplacée au moment de l’envoi.</small></div></div><div class="variable-list">${crmTemplateVariables.map(([code,label])=>`<button type="button" data-copy-variable="${esc(code)}" title="Copier ${esc(code)}"><code>${esc(code)}</code><span>${esc(label)}</span></button>`).join('')}</div></section>`};
function templatesPage(){
 const automatic=templates.automatic_email||[],automaticMeta=templates.automatic_meta||[];
 const automaticMetaSection=`<details class="card automatic-template-card" open><summary class="card-head"><div><h2>Messages automatiques META A3P</h2><small>E-mail et SMS envoyés aux nouveaux prospects A3P reçus depuis Facebook ou Instagram. Ces modèles sont affichés en lecture seule.</small></div><span class="automatic-template-meta"><span class="automatic-template-count">${automaticMeta.length} message${automaticMeta.length>1?'s':''}</span><span class="automatic-template-chevron" aria-hidden="true">⌄</span></span></summary><div class="template-list">${automaticMeta.map((t,i)=>`<div class="template-row"><div class="template-summary"><b>${esc(t.nom)}</b><small>${t.type==='email'?esc(t.sujet):esc(t.contenu).slice(0,110)}</small><span class="automatic-template-badge">${t.type==='email'?'E-mail':'SMS'} automatique · META · A3P</span></div><div class="template-actions"><button class="btn" data-preview-automatic-meta="${i}" aria-label="Prévisualiser ${esc(t.nom)}">Prévisualiser</button></div></div>`).join('')||'<div class="empty">Aucun message automatique META</div>'}</div></details>`;
 const automaticSection=`<details class="card automatic-template-card"><summary class="card-head"><div><h2>E-mails automatiques du formulaire</h2><small>E-mails envoyés après une demande d’informations formation. Ils sont gérés par le formulaire et affichés ici en lecture seule.</small></div><span class="automatic-template-meta"><span class="automatic-template-count">${automatic.length} formation${automatic.length>1?'s':''}</span><span class="automatic-template-chevron" aria-hidden="true">⌄</span></span></summary><div class="template-list">${automatic.map((t,i)=>`<div class="template-row"><div class="template-summary"><b>${esc(t.nom)}</b><small>${esc(t.sujet)}</small><span class="automatic-template-badge">Envoi automatique · ${esc(t.formation)}</span></div><div class="template-actions"><button class="btn" data-preview-automatic-template="${i}" aria-label="Prévisualiser l’e-mail automatique ${esc(t.nom)}">Prévisualiser</button></div></div>`).join('')||'<div class="empty">Aucun e-mail automatique</div>'}</div></details>`;
 page.innerHTML=header('BIBLIOTHÈQUE','Modèles de messages','Consultez les e-mails automatiques et créez vos propres modèles e-mail HTML et SMS.')+automaticMetaSection+templateVariablesHtml()+`<div class="template-grid">${['email','sms'].map(type=>`<section class="card"><div class="card-head"><h2>${type==='email'?'Modèles e-mail personnalisés':'Modèles SMS'}</h2><button class="btn blue" data-add-template="${type}">＋ ${type==='email'?'Ajouter un mail':'Ajouter un SMS'}</button></div><div class="template-list">${templates[type].map((t,i)=>`<div class="template-row"><div class="template-summary"><b>${esc(t.nom)}</b><small>${type==='email'?esc(t.sujet):esc(t.contenu).slice(0,80)}</small></div><div class="template-actions"><button class="btn" data-preview-template="${i}" data-preview-type="${type}" aria-label="Prévisualiser le modèle ${esc(t.nom)}">Prévisualiser</button><button class="btn" data-edit-template="${i}" data-edit-type="${type}" aria-label="Modifier le modèle ${esc(t.nom)}">Modifier</button><button class="btn danger" data-delete-template="${i}" data-delete-type="${type}" aria-label="Supprimer le modèle ${esc(t.nom)}">Supprimer</button></div></div>`).join('')||'<div class="empty">Aucun modèle</div>'}</div></section>`).join('')}</div>`+automaticSection;
 document.querySelectorAll('[data-copy-variable]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.dataset.copyVariable);toast(`Variable ${b.dataset.copyVariable} copiée`)});
 document.querySelectorAll('[data-add-template]').forEach(b=>b.onclick=()=>b.dataset.addTemplate==='email'?emailTemplateChoiceModal():templateModal('sms'));
 document.querySelectorAll('[data-edit-template]').forEach(b=>b.onclick=()=>templateModal(b.dataset.editType,templates[b.dataset.editType][Number(b.dataset.editTemplate)]));
 document.querySelectorAll('[data-delete-template]').forEach(b=>b.onclick=()=>deleteTemplate(b.dataset.deleteType,templates[b.dataset.deleteType][Number(b.dataset.deleteTemplate)]));
 document.querySelectorAll('[data-preview-automatic-meta]').forEach(b=>b.onclick=()=>{const t=automaticMeta[Number(b.dataset.previewAutomaticMeta)];if(!t)return;if(t.type==='sms')previewModal(smsPreviewHtml(t.contenu),false,null,{contenu:t.contenu,destinataire:''});else previewModal(t.contenu,true,{sujet:t.sujet,contenu:t.contenu})});
 document.querySelectorAll('[data-preview-automatic-template]').forEach(b=>b.onclick=()=>{const t=automatic[Number(b.dataset.previewAutomaticTemplate)];if(t)previewModal(t.contenu,true)});
 document.querySelectorAll('[data-preview-template]').forEach(b=>b.onclick=()=>{const type=b.dataset.previewType,t=templates[type][Number(b.dataset.previewTemplate)];if(!t)return;if(type==='sms')previewModal(smsPreviewHtml(t.contenu),false,null,{contenu:t.contenu});else previewModal(t.contenu,true,{sujet:t.sujet,contenu:t.contenu})});
 if(window.CRMWorkspace)CRMWorkspace.enhanceTemplates(workspaceContext());
}
function emailTemplateChoiceModal(){modal('Ajouter un mail',`<p class="template-choice-intro">Comment souhaitez-vous créer votre modèle d’e-mail ?</p><div class="template-choice-grid"><button type="button" class="template-choice" id="useEmailStarter"><b>Utiliser le modèle existant</b><span>Gardez la mise en page Intégrale Academy et saisissez simplement le contenu de votre e-mail.</span></button><button type="button" class="template-choice" id="pasteEmailHtml"><b>Coller un code HTML</b><span>Commencez avec un éditeur vide pour coller votre propre e-mail HTML.</span></button></div>`,'');useEmailStarter.onclick=()=>templateModal('email',null,templates.email_starter||'');pasteEmailHtml.onclick=()=>templateModal('email')}
const emailContentPattern=/<!-- EMAIL_CONTENT_START -->([\s\S]*?)<!-- EMAIL_CONTENT_END -->/;
const emailHeaderPatterns={title:/<!-- EMAIL_HEADER_TITLE_START -->([\s\S]*?)<!-- EMAIL_HEADER_TITLE_END -->/,subtitle:/<!-- EMAIL_HEADER_SUBTITLE_START -->([\s\S]*?)<!-- EMAIL_HEADER_SUBTITLE_END -->/,tagline:/<!-- EMAIL_HEADER_TAGLINE_START -->([\s\S]*?)<!-- EMAIL_HEADER_TAGLINE_END -->/};
function emailContentToHtml(content){return String(content||'').trim().split(/\n\s*\n/).filter(Boolean).map(paragraph=>`<p>${esc(paragraph).replace(/\n/g,'<br>')}</p>`).join('')}
function emailContentToText(html){const container=document.createElement('div');container.innerHTML=html;container.querySelectorAll('br').forEach(br=>br.replaceWith('\n'));container.querySelectorAll('p').forEach(p=>p.insertAdjacentText('afterend','\n\n'));return container.textContent.trim()}
function replaceEmailMarker(html,pattern,startMarker,endMarker,value){return html.replace(pattern,`${startMarker}${esc(value)}${endMarker}`)}
function templateModal(type,existing=null,starter=''){const mail=type==='email',editing=!!existing,initialBody=existing?.contenu||starter,usesStarter=mail&&emailContentPattern.test(initialBody),contentMatch=usesStarter?initialBody.match(emailContentPattern):null,hasEditableHeader=usesStarter&&Object.values(emailHeaderPatterns).every(pattern=>pattern.test(initialBody));modal(`${editing?'Modifier':'Nouveau'} modèle ${mail?'e-mail':'SMS'}`,`<div class="field"><label>Nom du modèle</label><input id="tplName" placeholder="Ex. Confirmation RDV" value="${esc(existing?.nom||'')}"></div>${mail?`<div class="field"><label>Objet</label><input id="tplSubject" value="${esc(existing?.sujet||'')}"></div>`:''}${usesStarter?`${hasEditableHeader?`<fieldset class="email-header-fields"><legend>Header du mail</legend><small class="field-help">Personnalisez les trois textes du bandeau bleu. Les variables comme {{ formation }} sont acceptées.</small><div class="field"><label for="tplHeaderTitle">Titre</label><input id="tplHeaderTitle" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.title)[1]))}"></div><div class="field"><label for="tplHeaderSubtitle">Sous-titre</label><input id="tplHeaderSubtitle" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.subtitle)[1]))}"></div><div class="field"><label for="tplHeaderTagline">Accroche</label><input id="tplHeaderTagline" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.tagline)[1]))}"></div></fieldset>`:''}<div class="field email-content-field"><label for="tplContent">Contenu du mail</label><small class="field-help">Saisissez uniquement votre message : la mise en page du modèle est conservée automatiquement.</small><textarea id="tplContent" rows="8" placeholder="Rédigez ici le contenu de votre e-mail…">${esc(emailContentToText(contentMatch[1]).replace('Écrivez ici le contenu de votre e-mail.',''))}</textarea></div><details class="email-code-details"><summary>Modifier le code HTML (avancé)</summary><div class="field"><textarea id="tplBody" aria-label="Code HTML du modèle">${esc(initialBody)}</textarea></div></details>`:`<div class="field"><label>${mail?'Code HTML':'Texte du SMS'}</label>${mail?'<small class="field-help">Le code complet reste modifiable et peut être récupéré à tout moment via « Prévisualiser », puis « Copier le code HTML ».</small>':''}<textarea id="tplBody" style="min-height:320px" placeholder="${mail?'Collez ici votre code HTML…':'Bonjour…'}">${esc(initialBody)}</textarea></div>`}`,`<button class="btn blue" id="saveTpl">${editing?'Enregistrer les modifications':'Enregistrer le modèle'}</button>`);if(usesStarter){tplContent.oninput=()=>{tplBody.value=tplBody.value.replace(emailContentPattern,`<!-- EMAIL_CONTENT_START -->${emailContentToHtml(tplContent.value)}<!-- EMAIL_CONTENT_END -->`)};if(hasEditableHeader){const syncHeader=()=>{tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.title,'<!-- EMAIL_HEADER_TITLE_START -->','<!-- EMAIL_HEADER_TITLE_END -->',tplHeaderTitle.value);tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.subtitle,'<!-- EMAIL_HEADER_SUBTITLE_START -->','<!-- EMAIL_HEADER_SUBTITLE_END -->',tplHeaderSubtitle.value);tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.tagline,'<!-- EMAIL_HEADER_TAGLINE_START -->','<!-- EMAIL_HEADER_TAGLINE_END -->',tplHeaderTagline.value)};[tplHeaderTitle,tplHeaderSubtitle,tplHeaderTagline].forEach(input=>input.oninput=syncHeader)}document.querySelector('.email-code-details').ontoggle=e=>{if(e.currentTarget.open){const match=tplBody.value.match(emailContentPattern);if(match)tplContent.value=emailContentToText(match[1])}}}saveTpl.onclick=async()=>{if(!tplName.value.trim()||!tplBody.value.trim()||(usesStarter&&!tplContent.value.trim()))return toast('Le nom et le contenu sont obligatoires',true);saveTpl.disabled=true;try{const t=await api(editing?`/api/crm/templates/${existing.id}`:'/api/crm/templates',{method:editing?'PATCH':'POST',body:JSON.stringify({type,nom:tplName.value,sujet:mail?tplSubject.value:'',contenu:tplBody.value})});if(editing)templates[type][templates[type].findIndex(x=>x.id===existing.id)]=t;else templates[type].push(t);closeModal();templatesPage();toast(editing?'Modèle modifié':'Modèle enregistré')}catch(e){toast(e.message,true);saveTpl.disabled=false}}}
async function deleteTemplate(type,t){if(!t||!window.confirm(`Supprimer définitivement le modèle « ${t.nom} » ?`))return;try{await api(`/api/crm/templates/${t.id}`,{method:'DELETE'});templates[type]=templates[type].filter(x=>x.id!==t.id);templatesPage();toast('Modèle supprimé')}catch(e){toast(e.message,true)}}
async function createContact(){modal('Créer une nouvelle piste',`<div class="fields"><div class="field"><label>Prénom</label><input id="newFirst"></div><div class="field"><label>Nom</label><input id="newLast"></div><div class="field full"><label>Formation</label><select id="newTraining">${['APS','A3P','DESP','SSIAP 1','Chauffeur VTC'].map(x=>`<option>${x}</option>`)}</select></div></div>`,`<button class="btn blue" id="createBtn">Créer la piste</button>`);createBtn.onclick=async()=>{if(!newFirst.value&&!newLast.value)return toast('Renseignez au moins un nom',true);try{const c=await api('/api/crm/contacts',{method:'POST',body:JSON.stringify({prenom:newFirst.value,nom:newLast.value,formation:newTraining.value})});contacts.unshift(c);closeModal();showContact(c.id);toast('Nouvelle piste créée')}catch(e){toast(e.message,true)}}}
function deleteCrmDatabaseModal(){adminToolsMenuElement?.classList.remove('open');adminToolsButton?.setAttribute('aria-expanded','false');modal('Supprimer la base de données',`<div class="database-delete-warning"><b>Cette action est irréversible.</b><p>Tous les prospects, toutes les pistes et leur historique CRM seront définitivement supprimés. Les autres données du site ne seront pas affectées.</p><label for="deleteCrmConfirmation">Saisissez <strong>SUPPRIMER</strong> pour confirmer</label><input id="deleteCrmConfirmation" autocomplete="off" placeholder="SUPPRIMER"></div>`,`<button class="btn" id="cancelDatabaseDelete">Annuler</button><button class="btn danger" id="confirmDatabaseDelete" disabled>Supprimer définitivement</button>`,'database-delete-modal');const confirmation=document.querySelector('#deleteCrmConfirmation'),submit=document.querySelector('#confirmDatabaseDelete');document.querySelector('#cancelDatabaseDelete').onclick=closeModal;confirmation.oninput=()=>{submit.disabled=confirmation.value.trim()!=='SUPPRIMER'};submit.onclick=async()=>{submit.disabled=true;submit.textContent='Suppression…';try{const result=await api('/api/crm/database',{method:'DELETE'});contacts=[];crmAppointments=[];notifications=[];localStorage.removeItem('crm-recent-searches');closeModal();C.section='accueil';history.pushState({},'',`/crm`);render();updateNotificationCount();toast(`${result.deleted_count} fiche${result.deleted_count>1?'s':''} supprimée${result.deleted_count>1?'s':''}`)}catch(e){submit.disabled=false;submit.textContent='Supprimer définitivement';toast(e.message,true)}};confirmation.focus()}
let integrationTimer;function scheduleContactIntegrations(c){clearTimeout(integrationTimer);integrationTimer=setTimeout(()=>{loadCalendlyAppointments(c,true);refreshFundingBadges(c)},300)}
function render(){
 stopActiveVoiceDictation();
 window.CRMDocumentTitle.applySection(C.section,C.page_label);
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===C.section));updateLeadCount();
 if(C.section==='accueil'){page.innerHTML=dashboard();bindDashboard();document.querySelector('.page-title')?.insertAdjacentHTML('afterend',dashboardExportButton);return}
 if(C.section==='exports'){page.innerHTML=exportsPage();return}
 if(C.section==='calendrier')return calendarPage();
 if(C.section==='pistes'){page.innerHTML=listPage(C.section);bindList(C.section);bindRows();return}
 if(C.section==='relances'&&window.CRMWorkspace)return CRMWorkspace.remindersPage(workspaceContext());
 if(C.section==='demandes-rappel')return callbackRequestsPage();
 if(C.section==='notifications'&&window.CRMWorkspace)return CRMWorkspace.activityPage(workspaceContext(),'mentions');
 if(C.section==='fil-actu'&&window.CRMWorkspace)return CRMWorkspace.activityPage(workspaceContext(),'publications');
 if(C.section==='modeles'){templatesPage();return}
 if(window.CRMWorkspace){page.innerHTML=CRMWorkspace.listPage(C.section,workspaceContext());CRMWorkspace.bindList(C.section,workspaceContext());return}
 page.innerHTML=listPage(C.section);bindList(C.section);bindRows();
}
async function init(){try{const snapshot=await api(`/api/crm/bootstrap?section=${encodeURIComponent(C.section)}`);contacts=snapshot.contacts||[];templates=snapshot.templates||{email:[],sms:[]};formationSessions=snapshot.formation_sessions||{};notifications=snapshot.notifications||[];callbackRequests=snapshot.callback_requests||[];callbackRequestPendingCount=Math.max(0,Number(snapshot.callback_pending_count)||0);crmAppointments=snapshot.appointments||[];crmSettings=snapshot.settings||{};updateNotificationCount();updateCallbackRequestNavCount();const fiche=new URLSearchParams(location.search).get('fiche');fiche?await showContact(fiche):render();if(!fiche&&C.section==='pistes')refreshCrmSnapshot()}catch(e){page.innerHTML=`<div class="empty">Impossible de charger le CRM.<br>${esc(e.message)}</div>`}}
function developmentSupportModal(){
 modal('Support développement',`<form id="developmentSupportForm" class="fields" enctype="multipart/form-data"><div class="field"><label for="developmentSupportPlatform">Plateforme concernée</label><select id="developmentSupportPlatform" name="platform" required><option value="CRM">CRM</option><option value="Gestion stagiaires">GESTION STAGIAIRES</option><option value="Site internet officiel">SITE OFFICIEL</option></select></div><div class="field full"><label for="developmentSupportUrl">URL de la page concernée</label><input id="developmentSupportUrl" name="page_url" type="url" value="${esc(location.href)}" maxlength="2000" required></div><div class="field full"><label for="developmentSupportActions">Actions à mener</label><textarea id="developmentSupportActions" name="actions" rows="8" minlength="20" maxlength="6000" placeholder="Décrivez précisément toutes les modifications et le résultat attendu." required></textarea><small>La demande sera reformulée par l’IA, puis le texte original sera aussi conservé dans Notion.</small></div><div class="field full"><label for="developmentSupportAttachment">Pièce jointe (facultative)</label><input id="developmentSupportAttachment" name="attachment" type="file" accept=".png,.jpg,.jpeg,.webp,.gif,.heic,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt"><small>Image, PDF, document Word/Excel, CSV ou TXT · 20 Mo maximum. Les images seront affichées directement dans la page Notion.</small></div></form>`,`<button class="btn" id="developmentSupportCancel">Annuler</button><button class="btn blue" id="developmentSupportSubmit">ENVOYER</button>`,'development-support-modal');
 const form=document.querySelector('#developmentSupportForm'),cancel=document.querySelector('#developmentSupportCancel'),submit=document.querySelector('#developmentSupportSubmit');
 cancel.onclick=closeModal;
 submit.onclick=()=>form.requestSubmit();
 form.onsubmit=async event=>{
  event.preventDefault();
  const attachment=form.elements.attachment.files[0];
  if(attachment&&attachment.size>20*1024*1024)return toast('La pièce jointe ne doit pas dépasser 20 Mo.',true);
  submit.disabled=true;cancel.disabled=true;submit.textContent='Envoi…';
  try{
   const result=await api('/api/crm/development-support',{method:'POST',headers:{},timeout:90000,body:new FormData(form)});
   const attachmentText=result.attachment_uploaded?' La pièce jointe a également été ajoutée à la page.':'';
   modal('Demande envoyée',`<p>La demande a été reformulée et ajoutée à Notion avec le statut <strong>À traiter</strong>.${attachmentText}</p><p><a class="btn blue" href="${esc(result.url)}" target="_blank" rel="noopener noreferrer">Ouvrir dans Notion</a></p>`,`<button class="btn" id="developmentSupportDone">Fermer</button>`,'development-support-modal');
   document.querySelector('#developmentSupportDone').onclick=closeModal;
  }catch(error){
   submit.disabled=false;cancel.disabled=false;submit.textContent='ENVOYER';toast(error.message,true);
  }
 };
}
const newContactButton=document.querySelector('#newContact'),menuToggleButton=document.querySelector('#menuToggle'),sidebarCollapseButton=document.querySelector('#sidebarCollapse'),adminToolsButton=document.querySelector('#adminToolsBtn'),adminToolsMenuElement=document.querySelector('#adminToolsMenu'),developmentSupportButton=document.querySelector('#developmentSupportBtn');
async function loadBrevoSmsCredits(){const balance=document.querySelector('#brevoSmsCredits');if(!balance)return;balance.classList.remove('error');balance.removeAttribute('title');balance.textContent='Actualisation…';try{const result=await api('/api/crm/brevo/sms-credits'),smsRemaining=brevoCreditsToSms(result?.credits);if(smsRemaining===null)throw Error('Le solde SMS Brevo est invalide.');const formattedCredits=formatBrevoCredits(result.credits);balance.textContent=`${new Intl.NumberFormat('fr-FR').format(smsRemaining)} SMS restant${smsRemaining>1?'s':''}`;balance.title=`Solde Brevo : ${formattedCredits} crédit${Number(result.credits)>1?'s':''}`}catch(e){balance.textContent=e.message;balance.classList.add('error')}}
newContactButton.addEventListener('click',()=>window.CRMWorkspace?CRMWorkspace.createContactModal(workspaceContext()):createContact());developmentSupportButton?.addEventListener('click',()=>{adminToolsMenuElement?.classList.remove('open');adminToolsButton?.setAttribute('aria-expanded','false');developmentSupportModal()});document.querySelector('#manageStatusesTop')?.addEventListener('click',statusesModal);document.querySelector('#deleteCrmDatabase')?.addEventListener('click',deleteCrmDatabaseModal);window.CRMSidebarState?.initialize(document);adminToolsButton?.addEventListener('click',e=>{e.stopPropagation();const opening=!adminToolsMenuElement.classList.contains('open');adminToolsMenuElement.classList.toggle('open',opening);adminToolsButton.setAttribute('aria-expanded',opening);if(opening)loadBrevoSmsCredits()});const searchBox=document.querySelector('.search');searchBox.insertAdjacentHTML('beforeend','<div class="global-results" id="globalResults"></div>');
const normalizeGlobalSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr-FR').trim();
const normalizePhoneSearch=value=>{let digits=String(value||'').replace(/\D/g,''),frenchPrefix=false;if(digits.startsWith('0033')){digits=digits.slice(4);frenchPrefix=true}else if(digits.startsWith('33')){digits=digits.slice(2);frenchPrefix=true}if(frenchPrefix&&digits.length===9)digits=`0${digits}`;return digits};
const phoneSearchQuery=value=>{const raw=String(value||'').trim();if(!/^[+\d\s().\/-]+$/.test(raw))return'';const digits=normalizePhoneSearch(raw);return digits.length>=3?digits:''};
const contactSearchFields=c=>[c.prenom,c.nom,c.mail,c.telephone,c.formation,c.lieu,c.statut];
const searchable=c=>normalizeGlobalSearch(contactSearchFields(c).join(' '));
const contactMatchesSearch=(contact,query)=>{const normalized=normalizeGlobalSearch(query);if(!normalized)return true;if(searchable(contact).includes(normalized))return true;const phoneQuery=phoneSearchQuery(query);return!!phoneQuery&&normalizePhoneSearch(contact.telephone).includes(phoneQuery)};
function contactSearchRank(c,q){const phoneQuery=phoneSearchQuery(q),phone=normalizePhoneSearch(c.telephone);if(phoneQuery){if(phone===phoneQuery)return 0;if(phone.startsWith(phoneQuery))return 1;if(phone.includes(phoneQuery))return 2;return 3}const names=[c.nom,c.prenom,displayName(c),`${c.nom||''} ${c.prenom||''}`].map(normalizeGlobalSearch);if(names.some(value=>value===q))return 0;if(names.some(value=>value.startsWith(q)))return 1;if(names.some(value=>value.includes(q)))return 2;return 3}
const prepareGlobalContactLinks=()=>document.querySelectorAll('button[data-global-id]').forEach(button=>{const link=document.createElement('a');link.dataset.globalId=button.dataset.globalId;link.href=contactSheetUrl(button.dataset.globalId);link.target='_blank';link.rel='noopener';link.innerHTML=button.innerHTML;button.replaceWith(link)});
new MutationObserver(prepareGlobalContactLinks).observe(globalResults,{childList:true});
globalResults.addEventListener('click',event=>{const link=event.target.closest('a[data-global-id]');if(!link)return;const contact=contacts.find(item=>String(item.id)===link.dataset.globalId);if(contact)saveRecent(contact);globalSearch.value='';globalResults.classList.remove('open')});
const searchPages=[['Accueil','accueil','/crm'],['Calendrier','calendrier','/crm/calendrier'],['Notifications','notifications','/crm/notifications'],['Fil actu','fil-actu','/crm/fil-actu'],['Pistes','pistes','/crm/pistes'],['Relances','relances','/crm/relances'],['Inscrits','inscrits','/crm/inscrits'],['Disqualifiés','disqualifies','/crm/disqualifies'],['Contacts','contacts','/crm/contacts'],['Modèles','modeles','/crm/modeles']];const recentSearches=()=>JSON.parse(localStorage.getItem('crm-recent-searches')||'[]');const saveRecent=c=>{const next=[c.id,...recentSearches().filter(id=>id!==c.id)].slice(0,5);localStorage.setItem('crm-recent-searches',JSON.stringify(next))};function renderGlobalSearch(){const q=normalizeGlobalSearch(globalSearch.value),recent=recentSearches().map(id=>contacts.find(c=>c.id===id)).filter(contact=>contact&&!contact.archived_at).slice(0,5),found=q?crmActiveContacts().filter(c=>contactMatchesSearch(c,q)).sort((a,b)=>contactSearchRank(a,q)-contactSearchRank(b,q)||displayName(a).localeCompare(displayName(b),'fr')).slice(0,5):recent,pageFound=q?searchPages.filter(([label])=>normalizeGlobalSearch(label).includes(q)).slice(0,5):[];globalResults.innerHTML=(found.length&&!q?'<p>5 dernières pistes consultées</p>':'')+found.map(c=>`<button data-global-id="${c.id}"><span class="avatar">${initials(c)}</span><span>${globalContactName(c)}<small>${esc(c.formation||'Dossier')} · ${esc(c.statut)} · ${esc(contactCoordinateSummary(c))}</small></span></button>`).join('')+pageFound.map(([label,section,url])=>`<button data-global-page="${section}" data-global-url="${url}"><span class="avatar page-avatar">⌁</span><span><b>${esc(label)}</b><small>Ouvrir la rubrique CRM</small></span></button>`).join('')||(q?'<p>Aucun résultat trouvé</p>':'');globalResults.classList.toggle('open',!!q||!!found.length);document.querySelectorAll('[data-global-id]').forEach(b=>b.onclick=()=>{const c=contacts.find(x=>x.id===b.dataset.globalId);if(c)saveRecent(c);globalSearch.value='';globalResults.classList.remove('open');showContact(b.dataset.globalId)});document.querySelectorAll('[data-global-page]').forEach(b=>b.onclick=()=>{C.section=b.dataset.globalPage;globalSearch.value='';globalResults.classList.remove('open');history.pushState({},'',b.dataset.globalUrl);render()})}globalSearch.onfocus=renderGlobalSearch;globalSearch.oninput=renderGlobalSearch;
document.addEventListener('click',e=>{if(!searchBox.contains(e.target))globalResults.classList.remove('open')});
globalSearch.onkeydown=e=>{if(e.key==='Enter'){C.section='contacts';history.pushState({},'',`/crm/contacts`);render();const x=document.querySelector('#listSearch');if(x){x.value=globalSearch.value;x.dispatchEvent(new Event('input'))}}};window.onpopstate=()=>location.reload();init();
// Synchronisation collaborative légère : une seule requête à la fois, uniquement
// lorsque l'onglet est visible. Un rechargement complet n'a lieu que si la liste
// des contacts a réellement changé.
const CRM_REFRESH_INTERVAL_MS=60000,CRM_CALENDLY_LIST_REFRESH_INTERVAL_MS=300000;
let crmRefreshTimer=null,crmRefreshInFlight=false,lastPipelineAppointmentRefreshAt=0,pipelineAppointmentRefreshInFlight=false;
async function refreshPipelineAppointments(now=Date.now()){
 if(C.section!=='pistes'||!C.is_admin||document.hidden||pipelineAppointmentRefreshInFlight)return false;
 if(lastPipelineAppointmentRefreshAt&&now-lastPipelineAppointmentRefreshAt<CRM_CALENDLY_LIST_REFRESH_INTERVAL_MS)return false;
 pipelineAppointmentRefreshInFlight=true;
 lastPipelineAppointmentRefreshAt=now;
 try{
  await api('/api/crm/calendly/sync',{method:'POST',body:JSON.stringify({restart:true}),timeout:60000});
  return true;
 }catch(error){
  if(error.status!==409)console.warn('Actualisation Calendly de la liste impossible',error);
  return false;
 }finally{pipelineAppointmentRefreshInFlight=false}
}
function scheduleCrmRefresh(delay=CRM_REFRESH_INTERVAL_MS){clearTimeout(crmRefreshTimer);crmRefreshTimer=setTimeout(refreshCrmSnapshot,delay)}
async function refreshCrmSnapshot(){
 if(document.hidden||crmRefreshInFlight){scheduleCrmRefresh();return}
 crmRefreshInFlight=true;
 try{
  const id=new URLSearchParams(location.search).get('fiche');
  const suffix=id?`?contact_id=${encodeURIComponent(id)}`:'';
  if(!id)await refreshPipelineAppointments();
  const snapshot=await api(`/api/crm/contacts/updates${suffix}`);
  const updates=snapshot.contacts||[];
  const hasAppointments=Array.isArray(snapshot.appointments);
  const appointmentsChanged=hasAppointments&&window.CRMAppointmentState.signature(snapshot.appointments)!==window.CRMAppointmentState.signature(crmAppointments);
  if(appointmentsChanged)crmAppointments=snapshot.appointments;
  const knownIds=new Set(contacts.map(contact=>String(contact.id)));
  const membershipChanged=updates.length!==contacts.length||updates.some(contact=>!knownIds.has(String(contact.id)));
  if(membershipChanged){
   const detailed=new Map(contacts.filter(contact=>!contact._summary).map(contact=>[String(contact.id),contact]));
   const fresh=await api(`/api/crm/contacts?section=${encodeURIComponent(C.section)}`);
   contacts=fresh.map(summary=>{
    const detail=detailed.get(String(summary.id));
    if(!detail)return summary;
    const merged={...summary,...detail};
    delete merged._summary;
    return merged;
   });
  }else updates.forEach(update=>mergeContactInStore(update.id,update));
  if(snapshot.selected)mergeContactInStore(snapshot.selected.id,snapshot.selected);
  updateLeadCount();
  updateVisibleAppointmentData();
  const current=id?contactInStore(id):null;
  if(current){
   const feedRoot=document.querySelector('#activityFeed'),pubRoot=document.querySelector('#publicationFeed');
   if(feedRoot)feedRoot.innerHTML=feed(current);
   if(pubRoot){pubRoot.innerHTML=publications(current);bindPublicationFeed(current,pubRoot)}
  }
 }catch(_){/* Une coupure réseau ne doit pas interrompre la saisie. */}
 finally{crmRefreshInFlight=false;scheduleCrmRefresh()}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){clearTimeout(crmRefreshTimer);refreshCrmSnapshot()}});scheduleCrmRefresh();
